 "content": "def transform(grid):
    h, wfull = len(grid), len(grid[0])
    # The framed pattern occupies the leading rectangle; its top row ends at the first zero.
    frame_color = grid[0][0]
    w = next((j for j, v in enumerate(grid[0]) if v == 0), wfull)
    # Collect each colored object on the right, represented as a normalized shape mask.
    objects = {}
    for r in range(h):
        for c in range(w, wfull):
            color = grid[r][c]
            if color != 0:
                objects.setdefault(color, set()).add((r, c))
    masks = {}
    for color, cells in objects.items():
        minr = min(r for r, _ in cells); maxr = max(r for r, _ in cells)
        minc = min(c for _, c in cells); maxc = max(c for _, c in cells)
        masks[color] = {(r-minr, c-minc) for r, c in cells}

    # Fully filled rows in the frame are separators between compartments.
    separators = [r for r in range(h) if all(grid[r][c] == frame_color for c in range(w))]
    out = [row[:w] for row in grid]
    for top, bottom in zip(separators, separators[1:]):
        holes = {(r-top-1, c-1) for r in range(top+1, bottom)
                 for c in range(1, w-1) if grid[r][c] == 0}
        if not holes:
            continue
        maxr = max(r for r, _ in holes); maxc = max(c for _, c in holes)
        # Interior masks use the compartment's full interior dimensions.
        target = {(r, c) for r in range(bottom-top-1) for c in range(w-2)
                  if grid[top+1+r][1+c] == 0}
        color = next((color for color, mask in masks.items() if mask == target), None)
        if color is None:
            # Shapes are expected to match exact zero-cell silhouettes.
            continue
        for r, c in target:
            out[top+1+r][1+c] = color
    return out
